-- 248_library_r8_questions_to_choice.sql
-- أسئلةُ كتب R8 الثمانية (M4) في مكتبة بيان — «الضغط على الجملة» و«حكمٌ ودليلُه» يصيران اختياراً من متعدّد
--
-- لماذا: تتمّةُ 241–247 على المستوى الثامن — كتبُه الثمانية المؤلَّفة في M4 (وكتبُ M3 الثلاثة المستوردة في ملفٍّ يليه).
--   بالقرار نفسه (المالك · ٢٦–٢٧ نوفمبر ٢٠٢٦) وبإذنه أن يُطبَّق كلُّ مستوىً مباشرة. الكتب 8 (لم تُنشر)، وأسئلتُها المحوَّلة 30
--   وخياراتُها الجديدة 120 — أربعةُ خياراتٍ من هذا المستوى كما في أسئلة الاختيار العشرة القائمة، وهي تبقى.
--   وحيث يصرّح سؤالٌ باقٍ بما كان سؤالُ الضغط يسأل عنه، سُئل تحت الهدف نفسه عن شيءٍ آخر.
--
-- كيف: يتحوّل السؤالُ في موضعه — المعرّفُ والترتيبُ والنصُّ المشترك كما هي — فتُحذف خياراتُه وتُكتب الجديدة ويُعاد مفتاحُه.
--   ولا طالبَ أجاب: الحارسُ يوقف الملفَّ إن وُجدت إجابةٌ واحدة على سؤالٍ منها.
--   وإعادةُ التشغيل آمنة: سؤالٌ صار mcq بنصّه الجديد يُتخطّى، وسؤالٌ على غير نمطه المقيس يرفع استثناءً فلا يُكتب شيء.
--   والمصدر خارج المستودع (فيه نصوصُ الكتب): Reading project/library-drafts/q-rewrite/R08.py ← gen_sql.py

do $$
declare
  spec jsonb := $spec$[
{"q": 13926, "quiz": 720, "was": "sentence", "obj": "P1.PARAPHRASE", "body": "Why is Mr. Din at home on Thursday?", "why": "السؤال يعيد صياغة النص: «His back is bad this week, and he is in bed at home.»", "opts": [{"t": "He has work at home.", "dx": "MIX", "key": false}, {"t": "His leg is bad.", "dx": null, "key": false}, {"t": "He is too cold.", "dx": "MIX", "key": false}, {"t": "His back is bad.", "dx": null, "key": true}]},
{"q": 13927, "quiz": 720, "was": "sentence", "obj": "P2.MOTIVE", "body": "On Friday, Mr. Din puts his hand on Sam's arm and keeps it there. Why does he do that?", "why": "الدافع يُستنتج من سلوكين في الفقرة: «He stops at the street and looks at the clean yard, and he does not say a word.» ثم يضع يده على ذراع سام.", "opts": [{"t": "He wants Sam to clean the yard again.", "dx": "JUMP", "key": false}, {"t": "He wants Sam to stop and go home.", "dx": "REV", "key": false}, {"t": "He wants to thank Sam for the clean yard.", "dx": null, "key": true}, {"t": "He is angry about the second brush.", "dx": "JUMP", "key": false}]},
